def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]

    total_my_d = my_actions.count('D')
    total_opp_d = opp_actions.count('D')

    my_last = my_actions[-1]
    opp_last = opp_actions[-1]
    my_second_last = my_actions[-2] if n >= 2 else 'C'
    opp_second_last = opp_actions[-2] if n >= 2 else 'C'

    if total_opp_d == 0:
        if total_my_d == 0:
            if n >= 5:
                return 'D'
            return 'C'
        else:
            return 'D'

    if n >= 5 and total_opp_d >= n * 0.7:
        return 'D'

    if n >= 2 and opp_last == 'D' and opp_second_last == 'D':
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if n >= 5 and total_opp_d >= n * 0.5:
                return 'D'
            return 'C'
        else:
            if n >= 2 and my_second_last == 'D':
                return 'C'
            if n >= 10 and total_opp_d <= n * 0.2:
                return 'C'
            return 'D'
    else:
        return 'C'
